    const limit = 1000000;
    let maxLen = 0;
    let maxStart = 0;
    for (let i = 1; i < limit; i++) {
        const clen = collatzLen(i);
        if (clen > maxLen) {
            maxLen = clen;
            maxStart = i;
        }
    }
    return maxStart;
}

function main() {
    const result = benchmark();

return result;
}
