const d3 = levenshtein(s1, s2);
const s3 = makeString("ab", 200);
const s4 = makeString("ba", 200);
const d4 = levenshtein(s3, s4);
return d1 === 3 && d2 === 3 && d3 === 500 && d4 === 2;
}
