const DEFAULT_OPTIONS = {
  printWidth: 80,
  semi: true,
  singleQuote: false,
  trailingComma: "all",
};
const BLOCKS = [
  { type: "heading", level: 1, text: "Formatter benchmark" },
  {
    type: "paragraph",
    text: "A larger source tree exercises nested AST traversal.",
  },
  { type: "list", items: ["parse", "attach comments", "print docs"] },
  {
    type: "paragraph",
    hidden: false,
    text: "The output must be stable across JavaScript and Lambda.",
  },
];
function cloneOptions(options = {}) {
  return { ...DEFAULT_OPTIONS, ...options };
}
function normalizeText(value) {
  return value.trim().replace(/\s+/g, " ");
}
function isVisible(node) {
  return node != null && node.hidden !== true;
}
function renderInline(node, index) {
  const text = normalizeText(node.text || "");
  return { kind: "text", index, text, marks: node.marks || [] };
}
function renderBlock(node, index, context) {
  if (!isVisible(node)) return null;
  if (node.type === "heading")
    return {
      ...renderInline(node, index),
      level: node.level || 1,
      kind: "heading",
    };
  if (node.type === "paragraph")
    return { ...renderInline(node, index), kind: "paragraph" };
  if (node.type === "list")
    return {
      kind: "list",
      items: node.items.map((item, itemIndex) =>
        renderInline({ text: item }, itemIndex),
      ),
      context,
    };
  return { kind: "unknown", value: node };
}
function renderDocument(document, options) {
  const config = cloneOptions(options);
  const result = [];
  for (const [index, node] of document.blocks.entries()) {
    const rendered = renderBlock(node, index, { config });
    if (rendered !== null) result.push(rendered);
  }
  return { title: document.title, config, blocks: result };
}
class SourcePrinter {
  constructor(options = {}) {
    this.options = cloneOptions(options);
  }
  print(document) {
    const output = renderDocument(document, this.options);
    const lines = [];
    for (const [index, block] of output.blocks.entries()) {
      lines.push(
        index +
          1 +
          ". " +
          block.kind +
          ": " +
          (block.text || block.value || ""),
      );
    }
    return lines.join("\n");
  }
}
function formatDocument(document, options = {}) {
  return new SourcePrinter(options).print(document);
}
const document = { title: "Formatter benchmark", blocks: BLOCKS };
const configuredOptions = { printWidth: 100, singleQuote: true };
const configured = formatDocument(document, configuredOptions);
const baseline = formatDocument(document);
const report = {
  configured,
  baseline,
  blockCount: document.blocks.length,
  visibleCount: baseline.split("\n").length,
};
const DEEP_TREE = {
  meta: {
    name: "nested-fixture",
    version: 3,
    flags: { stable: true, experimental: false },
    path: ["root", "content", "records"],
  },
  layer0: {
    layer1: {
      layer2: {
        layer3: {
          layer4: {
            layer5: {
              layer6: {
                layer7: {
                  layer8: {
                    layer9: {
                      layer10: {
                        layer11: {
                          leaf: { kind: "terminal", active: true, value: null },
                        },
                      },
                    },
                  },
                },
              },
            },
          },
        },
      },
    },
  },
  branches: [
    {
      id: "alpha",
      enabled: true,
      payload: {
        metrics: { count: 3, weight: 1.5 },
        tags: ["fast", "safe"],
        children: [
          { name: "a1", values: [1, 2, 3] },
          { name: "a2", values: [4, { deep: [5, 6, { terminal: "a" }] }] },
        ],
      },
    },
    {
      id: "beta",
      enabled: false,
      payload: {
        metrics: { count: 5, weight: 2.25 },
        tags: ["slow", "review"],
        children: [
          { name: "b1", values: [7, 8, { deep: [9, 10, { terminal: "b" }] }] },
        ],
      },
    },
    {
      id: "gamma",
      enabled: true,
      payload: {
        metrics: { count: 8, weight: 3.75 },
        tags: ["wide", "safe", "export"],
        children: [
          { name: "g1", values: [11, 12, 13] },
          {
            name: "g2",
            values: [14, 15, { deep: [16, 17, { terminal: "g" }] }],
          },
        ],
      },
    },
  ],
};
function collectNodes(
  root,
  options = {
    mode: "full",
    limit: 64,
    features: { metrics: true, paths: true },
  },
) {
  const entries = [];
  for (const branch of root.branches) {
    if (branch.enabled && branch.payload) {
      entries.push({
        id: branch.id,
        metrics: {
          count: branch.payload.metrics.count,
          weight: branch.payload.metrics.weight,
        },
        tags: branch.payload.tags,
        children: branch.payload.children,
        options,
      });
    } else {
      entries.push({ id: branch.id, skipped: true, reason: "disabled" });
    }
  }
  return { root, entries, options };
}
function scoreRecord(record) {
  let score = record.metrics.count * 2 + record.metrics.weight;
  if (record.tags.length > 2) {
    score = score + record.tags.length;
  }
  if (record.children.length > 1) {
    score = score + record.children[1].values[0];
  }
  return {
    id: record.id,
    score,
    detail: { tags: record.tags, first: record.children[0] },
  };
}
function walkLayers(tree) {
  const path = tree.meta.path;
  const terminal = tree.layer0;
  return { path, terminal, flags: tree.meta.flags };
}
function scoreEntry(entry) {
  if (entry.skipped) {
    return { id: entry.id, score: 0, detail: { reason: entry.reason } };
  }
  return scoreRecord(entry);
}
class Archive {
  constructor(snapshot) {
    this.snapshot = snapshot;
    this.entries = snapshot.entries;
  }
  describe() {
    return {
      name: this.snapshot.root.meta.name,
      count: this.entries.length,
      first: this.entries[0],
      terminal: this.snapshot.root.layer0,
    };
  }
  append(entry) {
    this.entries = this.entries.concat([entry]);
    return this.entries.length;
  }
}
const prepared = collectNodes(DEEP_TREE, {
  mode: "full",
  limit: 128,
  features: {
    metrics: true,
    paths: true,
    history: { enabled: true, depth: 12 },
  },
});
const scored = prepared.entries.map((entry) => scoreEntry(entry));
const walked = walkLayers(DEEP_TREE);
const archive = new Archive(prepared);
const archiveSize = archive.append({
  id: "delta",
  metrics: { count: 13, weight: 4.5 },
  tags: ["deep", "stable"],
  children: [{ name: "d1", values: [18, 19, { terminal: "d" }] }],
  options: prepared.options,
});
const finalReport = {
  prepared,
  scored,
  walked,
  archive: archive.describe(),
  archiveSize,
};
export { DEFAULT_OPTIONS, SourcePrinter, formatDocument, report };
