class Parser {
  constructor(string) {
    this.input = string;
    this.index = -1;
    this.line = 1;
    this.captureStart = -1;
    this.column = 0;
    this.current = null;
    this.captureBuffer = '';
  }

  parse() {
    this.read();
    this.skipWhiteSpace();
    const result = this.readValue();
    this.skipWhiteSpace();
    if (!this.isEndOfText()) {
      throw this.error('Unexpected character');
    }
    return result;
  }

  readValue() {
    switch (this.current) {
      case 'n':
        return this.readNull();
      case 't':
        return this.readTrue();
      case 'f':
        return this.readFalse();
      case '"':
        return this.readString();
      case '[':
        return this.readArray();
      case '{':
        return this.readObject();
      case '-':
      case '0':
      case '1':
      case '2':
      case '3':
      case '4':
      case '5':
      case '6':
      case '7':
      case '8':
      case '9':
        return this.readNumber();
      default:
        throw this.expected('value');
    }
  }

  readArray() {
    this.read();
    const array = new JsonArray();
    this.skipWhiteSpace();
    if (this.readChar(']')) {
      return array;
    }
    do {
      this.skipWhiteSpace();
      array.add(this.readValue());
      this.skipWhiteSpace();
    } while (this.readChar(','));
    if (!this.readChar(']')) {
      throw this.expected("',' or ']'");
    }
    return array;
  }

  readObject() {
    this.read();
    const object = new JsonObject();
    this.skipWhiteSpace();
    if (this.readChar('}')) {
      return object;
    }
    do {
      this.skipWhiteSpace();
      const name = this.readName();
      this.skipWhiteSpace();
      if (!this.readChar(':')) {
        throw this.expected("':'");
      }
      this.skipWhiteSpace();
      object.add(name, this.readValue());
      this.skipWhiteSpace();
    } while (this.readChar(','));

    if (!this.readChar('}')) {
      throw this.expected("',' or '}'");
    }
    return object;
  }

  readName() {
    if (this.current !== '"') {
      throw this.expected('name');
    }
    return this.readStringInternal();
  }

  readNull() {
    this.read();
    this.readRequiredChar('u');
    this.readRequiredChar('l');
    this.readRequiredChar('l');
    return JsonLiteral.NULL;
  }

  readTrue() {
    this.read();
    this.readRequiredChar('r');
    this.readRequiredChar('u');
    this.readRequiredChar('e');
    return JsonLiteral.TRUE;
  }

  readFalse() {
    this.read();
    this.readRequiredChar('a');
    this.readRequiredChar('l');
    this.readRequiredChar('s');
    this.readRequiredChar('e');
    return JsonLiteral.FALSE;
  }

  readRequiredChar(ch) {
    if (!this.readChar(ch)) {
      throw this.expected(`'${ch}'`);
    }
  }

  readString() {
    return new JsonString(this.readStringInternal());
  }

  readStringInternal() {
    this.read();
    this.startCapture();
    while (this.current !== '"') {
      if (this.current === '\\') {
        this.pauseCapture();
        this.readEscape();
        this.startCapture();
      } else {
        this.read();
      }
    }
    const string = this.endCapture();
    this.read();
    return string;
  }

  readEscape() {
    this.read();
    switch (this.current) {
      case '"':
      case '/':
      case '\\':
        this.captureBuffer += this.current;
        break;
      case 'b':
        this.captureBuffer += '\b';
        break;
      case 'f':
        this.captureBuffer += '\f';
        break;
      case 'n':
        this.captureBuffer += '\n';
        break;
      case 'r':
        this.captureBuffer += '\r';
        break;
      case 't':
        this.captureBuffer += '\t';
        break;
      default:
        throw this.expected('valid escape sequence');
    }
    this.read();
  }

  readNumber() {
    this.startCapture();
    this.readChar('-');
    const firstDigit = this.current;
    if (!this.readDigit()) {
      throw this.expected('digit');
    }
    if (firstDigit !== '0') {
      while (this.readDigit()) { /* no op */ }
    }
    this.readFraction();
    this.readExponent();
    return new JsonNumber(this.endCapture());
  }

  readFraction() {
    if (!this.readChar('.')) {
      return false;
    }
    if (!this.readDigit()) {
      throw this.expected('digit');
    }
    while (this.readDigit()) { /* no op */ }
    return true;
  }

  readExponent() {
    if (!this.readChar('e') && !this.readChar('E')) {
      return false;
    }
    if (!this.readChar('+')) {
      this.readChar('-');
    }
    if (!this.readDigit()) {
      throw this.expected('digit');
    }

    while (this.readDigit()) { /* no op */ }
    return true;
  }

  readChar(ch) {
    if (this.current !== ch) {
      return false;
    }
    this.read();
    return true;
  }

  readDigit() {
    if (!this.isDigit()) {
      return false;
    }
    this.read();
    return true;
  }

  skipWhiteSpace() {
    while (this.isWhiteSpace()) {
      this.read();
    }
  }

  read() {
    if ('\n' === this.current) {
      this.line += 1;
      this.column = 0;
    }
    this.index += 1;
    if (this.index < this.input.length) {
      this.current = this.input.substring(this.index, this.index + 1);
    } else {
      this.current = null;
    }
  }

  startCapture() {
    this.captureStart = this.index;
  }

  pauseCapture() {
    const end = this.current === null ? this.index : this.index - 1;
    this.captureBuffer += this.input.substring(this.captureStart, end + 1);
    this.captureStart = -1;
  }

  endCapture() {
    const end = this.current === null ? this.index : this.index - 1;
    let captured;
    if ('' === this.captureBuffer) {
      captured = this.input.substring(this.captureStart, end + 1);
    } else {
      this.captureBuffer += this.input.substring(this.captureStart, end + 1);
      captured = this.captureBuffer;
      this.captureBuffer = '';
    }
    this.captureStart = -1;
    return captured;
  }

  expected(expected) {
    if (this.isEndOfText()) {
      return this.error('Unexpected end of input');
    }
    return this.error(`Expected ${expected}`);
  }

  error(message) {
    return new ParseException(message, this.index, this.line, this.column - 1);
  }

  isWhiteSpace() {
    return ' ' === this.current || '\t' === this.current
      || '\n' === this.current || '\r' === this.current;
  }

  isDigit() {
    return '0' === this.current
      || '1' === this.current
      || '2' === this.current
      || '3' === this.current
      || '4' === this.current
      || '5' === this.current
      || '6' === this.current
      || '7' === this.current
      || '8' === this.current
      || '9' === this.current;
  }

  isEndOfText() {
    return this.current === null;
  }
}

