pn p_end_capture(var p) {
    var cur = (p.cur)
    var idx = (p.idx)
    var end = idx
    if (cur != "~") {
        end = idx - 1
    }
    var inp = (p.inp)
    var cs = (p.cs)
    var sub = slice(inp, cs, end + 1)
    var cbf = (p.cbf)
    var captured = sub
    if (cbf != 0) {
