    return this.children;
  }

  getParent() {
    return this.parent;
  }

  getNestingLevel() {
    return this.nestingLevel;
  }

  isRoot() {
    return this.isRoot_;
  }

  setParent(parent) {
    this.parent = parent;
    this.parent.addChildLoop(this);
  }

  setIsRoot() {
    this.isRoot_ = true;
