// R7RS Benchmark: tak (Node.js)
// Takeuchi function - tak(18, 12, 6) = 7
'use strict';

function tak(x, y, z) {
    if (y >= x) return z;
    const a = tak(x - 1, y, z);
    const b = tak(y - 1, z, x);
    const c = tak(z - 1, x, y);
    return tak(a, b, c);
}

function main() {
    const result = tak(18, 12, 6);

return result;
}
main()

