// R7RS Benchmark: sum (Node.js)
// Sum of integers from 0 to 10000, repeated 100 times
'use strict';

function run(n) {
    let i = n;
    let s = 0;
    while (i >= 0) {
        s = s + i;
        i = i - 1;
    }
    return s;
}

function main() {
    let result = 0;
    for (let iter = 0; iter < 100; iter++) {
        result = run(10000);
    }

return result;
}
main()

