// R7RS Benchmark: ack (Node.js)
// Ackermann function - ack(3, 8) = 2045
'use strict';

function ack(m, n) {
    if (m === 0) return n + 1;
    if (n === 0) return ack(m - 1, 1);
    return ack(m - 1, ack(m, n - 1));
}

function main() {
    const result = ack(3, 8);

return result;
}
main()

