// Larceny Benchmark: diviter (Node.js)
// Iterative integer division via repeated subtraction
'use strict';

function diviterDiv(x, y) {
    let q = 0;
    let r = x;
    while (r >= y) {
        r -= y;
        q++;
    }
    return q;
}

function diviterMod(x, y) {
    let r = x;
    while (r >= y) {
        r -= y;
    }
    return r;
