  const yDiv = (position.y / GOOD_VOXEL_SIZE) | 0;

  const result = new Vector2D();
  result.x = GOOD_VOXEL_SIZE * xDiv;
  result.y = GOOD_VOXEL_SIZE * yDiv;

  if (position.x < 0) {
    result.x -= GOOD_VOXEL_SIZE;
  }

  if (position.y < 0) {
    result.y -= GOOD_VOXEL_SIZE;
  }

  return result;
}

