        let location = lineNum + ':' + (i - lineStart + 1);
        let c = str[i]
        if (c == ' ')
            continue;
        if (c == '\n') {
            lineNum++;
            lineStart = i;
            continue;
        }
        if (c == '"' || c == "'") {
            let st = c
            let tok = ""
            let escaped = false
            let uniEsc
            let cu = 0
            for (i++; i < str.length; i++) {
                if (uniEsc) {
                    uniEsc--
                    cu *= 16
                    cu += Number.parseInt(str[i], 16)
