                tok += str[i++]
                while (isDigit(str[i]))
                    tok += str[i++]
            }
            if (str[i] == 'e' || str[i] == 'E') {
                tok += str[i++]
                if (str[i] == '+' || str[i] == '-')
                    tok += str[i++]
