        for (let l of this.lhs.apply(input, conf)) {
            let t = nameType(l)
            for (let i of this.index.apply(input, conf)) {
                if (t != 'array' && t != 'object' && t != 'null')
                    throw 'Cannot index ' + t + ' with ' + describeValue(i)
                if (t == 'array' && nameType(i) != 'number')
                    throw 'Cannot index array with ' + describeValue(i)
                else if (t == 'object' && nameType(i) != 'string')
                    throw 'Cannot index object with ' + describeValue(i)
                if (t == 'null') {
                    yield null
                    continue
                }
                if (t == 'array' && typeof i == 'number') {
                    if (Number.isNaN(i)) {
                        yield null
                        continue
                    }
                    let idx = i < 0 ? Math.ceil(l.length + i) : Math.floor(i)
                    yield typeof l[idx] == 'undefined' ? null : l[idx]
                } else {
                    yield typeof l[i] == 'undefined' ? null : l[i]
                }
            }
        }
    }
    * paths(input, conf) {
        for (let l of this.lhs.paths(input, conf))
            for (let a of this.index.apply(input, conf))
                yield l.concat([a])
    }
