        let t = nameType(input)
        if (t == 'null') return yield null;
        for (let i of this.index.apply(input, conf)) {
            if (t != 'array' && t != 'object')
                throw 'Cannot index ' + t + ' with ' + describeValue(i)
            if (t == 'array' && nameType(i) != 'number')
                throw 'Cannot index array with ' + describeValue(i)
            else if (t == 'object' && nameType(i) != 'string')
                throw 'Cannot index object with ' + describeValue(i)
            if (t == 'array' && typeof i == 'number') {
                if (Number.isNaN(i)) {
                    yield null
                    continue
                }
                let idx = i < 0 ? Math.ceil(input.length + i) : Math.floor(i)
                yield typeof input[idx] == 'undefined' ? null : input[idx]
            } else {
                yield typeof input[i] == 'undefined' ? null : input[i]
            }
        }
    }
    * paths(input, conf) {
        for (let a of this.index.apply(input, conf)) {
            if (typeof a != 'string' && typeof a != 'number')
                throw 'Cannot use ' + describeValue(a) + ' as object key'
            yield [a]
        }
    }
}
class IdentifierIndex extends GenericIndex {
    constructor(v) {
