        let s = ''
        for (let i = 0; i < this.strings.length; i++) {
            s += this.strings[i].replace('\\', '\\\\').replace('"', '\\"')
            if (this.interpolations[i])
                s += '\\(' + this.interpolations[i].toString() + ')'
        }
        return '"' + s + '"'
    }
}
