const formats = {
    text(v) {
        if (typeof v == 'string')
            return v
        return prettyPrint(v, '', '', '')
    },
    json(v) {
        return prettyPrint(v, '', '', '')
    },
    html(v) {
        if (typeof v != 'string')
            v = prettyPrint(v, '', '', '')
        return v.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(
            />/g, '&gt;').replace(/'/g, '&apos;').replace(/"/g, '&quot;')
    },
    uri(v) {
        if (typeof v != 'string')
            v = prettyPrint(v, '', '', '')
        return encodeURIComponent(v).replace(/[!'()*]/g,
            c => '%' + c.charCodeAt(0).toString(16).toUpperCase())
    },
    urid(v) {
        if (typeof v != 'string')
            v = prettyPrint(v, '', '', '')
        return decodeURIComponent(v)
    },
    csv(v) {
        if (nameType(v) != 'array')
            throw 'cannot csv-format ' + nameType(v) + ', only array'
        return v.map(x => {
            if (typeof x == 'string')
                return '"' + x.replace(/"/g, '""') + '"'
            else if (typeof x == 'number')
                return '' + x
            else if (x === null)
                return ''
            else
                throw 'type ' + nameType(x) + ' not valid in a csv row'
        }).join(',')
    },
    tsv(v) {
        if (nameType(v) != 'array')
            throw 'cannot tsv-format ' + nameType(v) + ', only array'
        return v.map(x => {
            if (typeof x == 'string')
                return x.replace(/\\/g, '\\\\').replace(/\t/g, '\\t')
                    .replace(/\r/g, '\\r').replace(/\n/g, '\\n')
            else if (typeof x == 'number')
                return '' + x
            else if (x === null)
                return ''
            else
                throw 'type ' + nameType(x) + ' not valid in a tsv row'
        }).join('\t')
    },
    base64(v) {
        if (typeof v != 'string')
            v = prettyPrint(v, '', '', '')
        return Buffer.from(v, 'utf8').toString('base64')
    },
    base64d(v) {
        if (typeof v != 'string')
            throw 'can only base64-decode strings'
        return Buffer.from(v, 'base64').toString('utf8')
    },
    sh(v) {
        let t = nameType(v)
        if (t == 'string')
            return "'" + v.replace(/'/g, "'\\''") + "'"
        else if (t == 'number')
            return '' + v
        else if (t == 'boolean')
            return '' + v
        else if (v === null)
            return 'null'
        else if (t === 'array') {
            return v.map(v => {
                let t = nameType(v)
                if (t == 'string')
                    return "'" + v.replace(/'/g, "'\\''") + "'"
                else if (t == 'number')
                    return '' + v
                else if (t == 'boolean')
                    return '' + v
                else if (v === null)
                    return 'null'
                else
                    throw t + ' cannot be escaped for shell'
            }).join(' ')
        } else
            throw t + ' cannot be escaped for shell'
    },
}

