            let conds = []
            let trueExprs = []
            let falseExpr = null
            while (tokens[i] && (tokens[i].type == 'if' || tokens[i].type == 'elif')) {
                let cond = parse(tokens, i + 1, ['then'])
                if (!tokens[cond.i] || tokens[cond.i].type != 'then')
