def b_range_prop: [{ from: 1, upto: range(-.; .), by: range(-.; .) | select(. != 0) } | ([range(.from; .upto; .by)] | length) == ([(.upto - .from) / .by | ceil, 0] | max)] | map(select(.)) | length;
