      (2048 | b_kv_update), (2048 | b_kv_entries), (1024 | b_ex_implode), (65536 | b_reduce),
      (65536 | b_try_catch), (1024 | b_repeat), (1024 | b_from), (65536 | b_last),
      (512 | b_pyramid), (12 | b_tree_contains), (12 | b_tree_flatten), (12 | b_tree_update),
