 * Compiles a jq program string into a generator function that produces all
 * the program's outputs given the initial input value.
 *
 * @param {string} prog - jq source code to compile.
 * @returns {((input: JQValue) => Generator<JQValue, void, unknown>) & {
 *   filter: {node: ParseNode},
 *   ast: ParseNode,
 *   trace: (input: any) => { node: null, output: any, next: any[] }
 * }} A function that applies the compiled filter to input data. The returned function
 * also has an `ast` property containing the parsed syntax tree, and a `trace` method
 * for tracing filter execution.
 */
function compile(prog) {
    let filter = parse(tokenise(prog).tokens)
    const ret = input => filter.node.apply(input, {
        userFuncArgs: {},
        variables: {}
    })
    ret.filter = filter
    ret.ast = filter.node
    ret.trace = (input) => {
        let dest = []
        filter.node.trace(input, {
            userFuncArgs: {},
            variables: {}
        }, dest)
        return {
            node: null,
            output: input,
            next: dest,
        }
    }
    return ret
}

function compileNode(prog) {
    return parse(tokenise(prog).tokens).node
}

function isAlpha(c) {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_'
}

function isDigit(c) {
    return (c >= '0' && c <= '9')
}

function prettyPrint(val, indent='', step='    ', LF='\n', truncateAt=0) {
    let SP = step ? ' ' : ''
    if (typeof val == 'undefined')
        return val
    if (val === null) {
        return 'null'
    } else if (val instanceof Array) {
        let ret = '['
        let first = true
        for (let v of Object.values(val)) {
            ret += (first ? '' : ',') + LF + indent + step +
                prettyPrint(v, indent + step, step, LF)
            first = false
        }
        ret += LF + indent + ']'
        return ret
    } else if (typeof val == 'object') {
        let ret = '{'
        let first = true
        for (let k of Object.keys(val)) {
            ret += (first ? '' : ',') + LF + indent + step +
                '"' + k + '":' +SP+ prettyPrint(val[k], indent + step, step, LF)
            first = false
        }
        ret += LF + indent + '}'
        return ret
    } else if (typeof val == 'string') {
        if (truncateAt && val.length > truncateAt)
            val = val.substring(0, truncateAt) + '...'
        return '"' + escapeString(val) + '"'
    } else if (typeof val == 'number') {
        return '' + val
    } else if (typeof val == 'boolean') {
        return val ? 'true' : 'false'
    }
}

function describeValue(val) {
    return nameType(val) + ' (' + prettyPrint(val, '', '', '', 24) + ')'
}

function isJqTruthy(val) {
    return val !== false && val !== null
}

function escapeString(s) {
    s = s.replace(/\\/g, '\\\\')
    s = s.replace(/"/g, '\\"')
    s = s.replace(/\n/g, '\\n')
    s = s.replace(/\t/g, '\\t')
    s = s.replace(/[\x00-\x1f]/g,
        x => '\\u00' + x.charCodeAt(0).toString(16).padStart(2, '0'))
    return s
}

function* zip(a, b) {
    let aa = a[Symbol.iterator]()
    let bb = b[Symbol.iterator]()
    let v1 = aa.next()
    let v2 = bb.next()
    while (!v1.done && !v2.done) {
        yield [v1.value, v2.value]
        v1 = aa.next()
        v2 = bb.next()
    }
}

// Implements the jq ordering algorithm, which is terrible.
function compareValues(a, b) {
    let at = nameType(a)
    let bt = nameType(b)
    if (at != bt) {
        return compareValues.typeOrder.indexOf(at) -
            compareValues.typeOrder.indexOf(bt)
    }
    if (at == 'boolean') {
        if (a && !b) return 1
        if (!a && b) return -1
    } else if (at == 'number') {
        return a - b
    } else if (at == 'string') {
        if (a < b) return -1
        if (b < a) return 1
    } else if (at == 'array') {
        for (let i = 0; i < a.length; i++) {
            let v1 = a[i]
            let v2 = b[i]
            if (typeof v1 == 'undefined' && typeof v2 != 'undefined')
                return -1
            else if (typeof v1 != 'undefined' && typeof v2 == 'undefined')
                return 1
            else if (typeof v1 == 'undefined') return 0
            let c = compareValues(v1, v2)
            if (c != 0) return c
        }
        if (a.length < b.length) return -1
        if (a.length > b.length) return 1
        return 0
    } else if (at == 'object') {
        let ka = Object.keys(a).sort()
        let kb = Object.keys(b).sort()
        let c = compareValues(ka, kb)
        if (c) return c
        for (let k of ka) {
            c = compareValues(a[k], b[k])
            if (c) return c
        }
    }
    return 0
}
compareValues.typeOrder = ['null', 'boolean', 'number', 'string',
                           'array', 'object']

function valueEquals(l, r) {
    let lt = nameType(l)
    let rt = nameType(r)
    if (lt != rt)
        return false
    if (lt == 'number')
        return (Number.isNaN(l) && Number.isNaN(r)) || l === r
    if (lt == 'string' || lt == 'boolean' || lt == 'null')
        return l === r
    if (lt == 'array') {
        if (l.length != r.length)
            return false
        for (let i = 0; i < l.length; i++)
            if (!valueEquals(l[i], r[i]))
                return false
        return true
    }
    let lk = Object.keys(l)
    let rk = Object.keys(r)
    if (lk.length != rk.length)
        return false
    for (let k of lk) {
        if (!r.hasOwnProperty(k))
            return false
        if (!valueEquals(l[k], r[k]))
            return false
    }
    return true
}

// Create a function from a program string.
//
// params is an array of parameter names
// body is a jq program as a string, which may use the parameters
//
// For example:
//     makeFunc(['f'], '[.[] | f]')
// defines the map function.
function makeFunc(params, body, pathFunc=false) {
    let c = compileNode(body)
    return makeUserFuncFromNode(params, c, pathFunc)
}

// [lambda patch] Lexical environments. A conf is never mutated after it is
// made: a call or a variable binding derives a new one, so a suspended
// generator keeps the scope it was created in. A call's argument frame
// chains to the frame of the def that lexically encloses the callee, not
// to the caller's frame, so a lookup costs the def nesting depth instead
// of the dynamic call depth, and each argument is a closure over the
// caller's conf.
const FRAME_DEF = Symbol('jqjs.frameDef')
// innermost def being parsed; a nested def records its nearest enclosing
// def that has parameters (only those make frames)
const defParseStack = []

function bindVariable(conf, name, value) {
    let variables = Object.create(conf.variables)
    variables[name] = value
    return {userFuncArgs: conf.userFuncArgs, variables}
}

function frameOwnerOf(frame) {
    return Object.prototype.hasOwnProperty.call(frame, FRAME_DEF) ? frame[FRAME_DEF] : null
}

// The frame of `def` on the lexical chain from `frame` (the root frame when
// def is null). A def called outside its lexical scope, which jqjs allows
// because definitions are global, falls back to the caller's frame.
function enclosingFrame(frame, def) {
    for (let f = frame; f; f = Object.getPrototypeOf(f)) {
        let owner = frameOwnerOf(f)
        if (owner === def) return f
        if (owner === null) return def === null ? f : frame
    }
    return frame
}

function enclosingFrameDef() {
    for (let i = defParseStack.length - 1; i >= 0; i--)
        if (defParseStack[i].params.length > 0) return defParseStack[i]
    return null
}

// Lift a node to a function
function makeUserFuncFromNode(params, node, pathFunc=false, def=null, frameParent=null) {
    let c = node
    let f = (x, conf) => c.apply(x, conf)
    if (pathFunc)
        f = (x, conf) => c.paths(x, conf)
    // every parameterised function owns its frames, shorthands included
    if (def === null) def = {params}
    let ret = function*(input, conf, args) {
        let frame = enclosingFrame(conf.userFuncArgs, frameParent)
        if (params.length > 0) {
            frame = Object.create(frame)
            frame[FRAME_DEF] = def
            for (let i = 0; i < params.length; i++)
                frame[params[i] + '/0'] = {node: args[i], conf}
        }
        yield* f(input, {userFuncArgs: frame, variables: conf.variables})
    }
    ret.params = Array.prototype.map.call(params, label => ({label, mode: 'defer'}))
    return ret;
}

// Define and save a function that is shorthand for a longer expression
//
// name is the name of the function
// params is an array of parameters, or a string of one-character names
// body is a jq program as a string
function defineShorthandFunction(name, params, body) {
    let fname = name + '/' + params.length
    functions[fname] = makeFunc(params, body)
    functions[fname].params = Array.prototype.map.call(params, label => ({label, mode: 'defer'}))
    functions[fname + '-paths'] = makeFunc(params, body, true)
}

// Recursive-descent parser for JQ query language

// Split input program into tokens. Tokens are:
// quote, number, identifier-index, dot-square, dot, left-square,
// right-square, left-paren, right-paren, pipe, comma,
// identifier, colon, left-brace, right-brace, semicolon, at,
// variable, as, reduce, foreach, def, import, include, question
// if, then, else, end, elif, try, catch
const KEYWORDS = ['as', 'reduce', 'foreach', 'import', 'include', 'def', 'if', 'then', 'else', 'end', 'elif', 'try', 'catch', 'and', 'or'];
function tokenise(str, startAt=0, parenDepth) {
    let ret = []
    function error(msg) {
        throw msg;
    }
    let i
    let lineNum = 1
    let lineStart = 0;
    toplevel: for (i = startAt; i < str.length; i++) {
        let location = lineNum + ':' + (i - lineStart + 1);
        let c = str[i]
        if (c == ' ')
            continue;
        if (c == '\n') {
            lineNum++;
            lineStart = i;
            continue;
        }
        if (c == '"' || c == "'") {
            let st = c
            let tok = ""
            let escaped = false
            let uniEsc
            let cu = 0
            for (i++; i < str.length; i++) {
                if (uniEsc) {
                    uniEsc--
                    cu *= 16
                    cu += Number.parseInt(str[i], 16)
                    if (uniEsc == 0) {
                        tok += String.fromCharCode(cu)
                        cu = 0
                    }
                } else if (escaped) {
                    let q = str[i]
                    if (q == '"' || q == "'") tok += q
                    else if (q == 'n') tok += '\n'
                    else if (q == 't') tok += '\t'
                    else if (q == 'r') tok += '\r'
                    else if (q == 'b') tok += '\b'
                    else if (q == 'f') tok += '\f'
                    else if (q == '/') tok += '/'
                    else if (q == '\\')tok += '\\'
                    else if (q == 'u') uniEsc = 4
                    else if (q == '(') {
                        // Interpolation
                        let r = tokenise(str, i + 1, 0)
                        ret.push({type: 'quote-interp', value: tok, location})
                        tok = ''
                        ret = ret.concat(r.tokens)
                        i = r.i
                    }
                    else throw "invalid escape " + q
                    escaped = false
                } else if (str[i] == '\\') {
                    escaped = true
                } else if (str[i] == st) {
                    ret.push({type: 'quote', value: tok, location})
                    continue toplevel
                } else {
                    escaped = false
                    tok += str[i]
                }
            }
            error("unterminated string literal")
        } else if (isDigit(c)) {
            let tok = ''
            while (isDigit(str[i]))
                tok += str[i++]
            if (str[i] == '.') {
                tok += str[i++]
                while (isDigit(str[i]))
                    tok += str[i++]
            }
            if (str[i] == 'e' || str[i] == 'E') {
                tok += str[i++]
                if (str[i] == '+' || str[i] == '-')
                    tok += str[i++]
                while (isDigit(str[i]))
                    tok += str[i++]
            }
            ret.push({type: 'number', value: Number.parseFloat(tok), location})
            i--
        } else if (c == '.') {
            let d = str[i+1]
            if (isAlpha(d)) {
                i++
                let tok = ''
                while (isAlpha(str[i]) || isDigit(str[i]))
                    tok += str[i++]
                ret.push({type: 'identifier-index', value: tok, location})
                i--
            } else if (d == '[') {
                i++
                ret.push({type: 'dot-square', location})
            } else if (d == '.') {
                i++
                ret.push({type: 'dot-dot', location})
            } else {
                ret.push({type: 'dot', location})
            }
        } else if (c == '$') {
            let d = str[i+1]
            i++
            let tok = ''
            while (isAlpha(str[i]) || isDigit(str[i])) {
                tok += str[i]
                i++
            }
            ret.push({type: 'variable', name: tok, location})
            i--
        } else if (c == '[') {
            ret.push({type: 'left-square', location})
        } else if (c == ']') {
            ret.push({type: 'right-square', location})
        } else if (c == '(') {
            ret.push({type: 'left-paren', location})
            parenDepth++
        } else if (c == ')') {
            ret.push({type: 'right-paren', location})
            parenDepth--
            if (parenDepth < 0)
                return {tokens: ret, i}
        } else if (c == '{') {
            ret.push({type: 'left-brace', location})
        } else if (c == '}') {
            ret.push({type: 'right-brace', location})
        } else if (c == ',') {
            ret.push({type: 'comma', location})
        } else if (c == ';') {
            ret.push({type: 'semicolon', location})
        } else if (c == '@') {
            ret.push({type: 'at', location})
        } else if (c == '?') {
            ret.push({type: 'question', location})
        } else if (c == '|') {
            let d = str[i+1]
            if (d == '=') {
                ret.push({type: 'pipe-equals', location})
                i++
            } else
                ret.push({type: 'pipe', location})
        // Infix operators
        } else if (c == '+' || c == '*' || c == '-' || c == '/' || c == '%'
                || c == '<' || c == '>') {
            if (c == '/' && str[i+1] == '/') {
                c = '//'
                i++
            }
            if (str[i+1] == '=') {
                if (c == '<' || c == '>')
                    ret.push({type: 'op', op: c + '=', location})
                else
                    ret.push({type: 'op-equals', op: c, location})
                i++
            } else
                ret.push({type: 'op', op: c})
        } else if (c == '=') {
            if (str[i + 1] != '=') {
                ret.push({type: 'equals'})
            } else {
                i++
                ret.push({type: 'op', op: '==', location})
            }
        } else if (c == '!') {
            if (str[i + 1] != '=')
                throw 'unexpected ! at ' + location
            i++
            ret.push({type: 'op', op: '!=', location})
        } else if (isAlpha(c)) {
            let tok = ''
            while (isAlpha(str[i]) || isDigit(str[i]) || str[i] == '_')
                tok += str[i++]
            if (tok == "and" || tok == "or") {
                ret.push({type: 'op', op: tok, value: tok, location})
            } else if (KEYWORDS.includes(tok)) {
                ret.push({type: tok, value: tok, location})
            } else {
                ret.push({type: 'identifier', value: tok, location})
            }
            i--
        } else if (c == ':') {
            ret.push({type: 'colon', location})
        } else if (c == '#') {
            while (str[i] != '\n' && str[i] != undefined)
                i++;
            lineNum++;
            lineStart = i;
        }
    }
    ret.push({type: '<end-of-program>', location: lineNum + ':' + (i - lineStart + 1)})
    return {tokens: ret, i}
}

function describeLocation(token) {
    if (token) {
        return token.location
    }
    return '<end>'
}

// Parse a token stream by recursive descent.
//
// Returns {node: {*apply(input, conf)}, i}, where i is the position in the
// token stream and node is one of the filtering nodes defined below.
// Returns at end of stream or when a token of type until is found.
/**
 * 
 * @param {any[]} tokens 
 * @param {number} startAt 
 * @param {string[]} until 
 * @param {boolean} maybePrefix Allow an "until" token in first position only
 * @returns { {node: ParseNode, i: number} }
 */
function parse(tokens, startAt=0, until=[], maybePrefix=false) {
    let i = startAt
    let t = tokens[i]
    let ret = []
    let commaAccum = []
    while (t && (until.indexOf(t.type) == -1 || (i == startAt && maybePrefix))) {
        // Simple cases
        if (t.type == 'identifier-index') {
            ret.push(new IdentifierIndex(t.value))
        } else if (t.type == 'number') {
            ret.push(new NumberNode(t.value))
        } else if (t.type == 'quote') {
            ret.push(new StringNode(t.value))
        } else if (t.type == 'dot') {
            if (tokens[i+1] && tokens[i+1].type == 'quote') {
                ret.push(new GenericIndex(new StringNode(tokens[i+1].value)))
                i++
            } else {
                ret.push(new IdentityNode())
            }
        } else if (t.type == 'dot-dot') {
            ret.push(new RecursiveDescent())
        } else if (t.type == 'identifier') {
            if (t.value == 'true' || t.value == 'false')
                ret.push(new BooleanNode(t.value == 'true'))
            else if (t.value == 'null')
                ret.push(new BooleanNode(null))
