            let stream = [lhs, t]
            let r = parse(tokens, i + 1, ['op', 'comma', 'pipe', 'right-paren',
                'right-brace', 'right-square', '<end-of-program>', 'as'].concat(until))
            i = r.i
            stream.push(r.node)
