        let i = this.interpolations[startAt]
        if (!i) return yield s
        for (let v of this.interpolations[startAt].apply(input, conf)) {
            for (let r of this.applyEscape(input, esc, conf, startAt + 1)) {
                yield s + esc(v) + r
