                tid == LMD_TYPE_BOOL ? K_BOOL : tid == LMD_TYPE_STRING ? K_STRING :
                tid == LMD_TYPE_NULL ? K_NULL : tid == LMD_TYPE_UNDEFINED ? K_UNDEFINED : K_ANY;
