                jump(c, done); put_label(c, scalar);
                for (int i = 0; i < 3; i++)
                    branch(c, MIR_BEQ, lanes[i], reg(c, storage), integer(c, scalars[i].type));
                put_label(c, shared);
                if (operation == LMD_PROP_SET) {
                    MIR_reg_t stored = em_call_3(&c->em, "map_field_store", MIR_T_I64,
