                ? name_pool_create_string(c->program->frontend->name_pool, ((AstIdentNode*)prop->key)->name) : NULL;
            LmdValue name = spelling ? boxed(c, constant(c, s2it(spelling)), K_STRING)
                : canonical_key(c, expression(c, prop->key));
