    }
    if (head->node_type == AST_NODE_ARRAY_PATTERN) {
        int i = 0;
        for (AstNode* e = ((AstArrayNode*)head)->item; e; e = e->next, i++) {
            LmdValue component = direct_pair ? boxed(c, components[i]) :
                array_read(c, {NULL, value, constant(c, i), true, i});
